const repoSpec = ($env.GITHUB_REPO || '').trim();
if (!repoSpec || !repoSpec.includes('/')) {
  throw new Error('Set GITHUB_REPO as owner/repo, for example anthropics/claude-code.');
}

const [owner, repo] = repoSpec.split('/');
const language = (($env.SUMMARY_LANGUAGE || 'EN').trim().toUpperCase() === 'FR') ? 'FR' : 'EN';
const destinationWebhookUrl = ($env.DESTINATION_WEBHOOK_URL || '').trim();
if (!destinationWebhookUrl) {
  throw new Error('Set DESTINATION_WEBHOOK_URL to a Discord webhook URL.');
}

const until = new Date();
const since = new Date(until);
since.setUTCDate(until.getUTCDate() - 7);

const headers = {
  Accept: 'application/vnd.github+json',
  'X-GitHub-Api-Version': '2022-11-28',
  'User-Agent': 'n8n-weekly-github-claude-summary'
};
if ($env.GITHUB_TOKEN) {
  headers.Authorization = `Bearer ${$env.GITHUB_TOKEN}`;
}

const github = async (path) => this.helpers.httpRequest({
  method: 'GET',
  url: `https://api.github.com/repos/${owner}/${repo}${path}`,
  headers,
  json: true
});

const sinceIso = since.toISOString();
const untilIso = until.toISOString();

const [commits, closedIssuesAndPrs, closedPrs] = await Promise.all([
  github(`/commits?since=${encodeURIComponent(sinceIso)}&until=${encodeURIComponent(untilIso)}&per_page=100`),
  github(`/issues?state=closed&since=${encodeURIComponent(sinceIso)}&per_page=100`),
  github('/pulls?state=closed&sort=updated&direction=desc&per_page=100')
]);

const inWindow = (dateValue) => dateValue && new Date(dateValue) >= since && new Date(dateValue) <= until;
const closedIssues = closedIssuesAndPrs
  .filter((issue) => !issue.pull_request && inWindow(issue.closed_at))
  .map((issue) => ({
    number: issue.number,
    title: issue.title,
    closed_at: issue.closed_at,
    url: issue.html_url,
    labels: (issue.labels || []).map((label) => label.name)
  }));

const mergedPullRequests = closedPrs
  .filter((pull) => inWindow(pull.merged_at))
  .map((pull) => ({
    number: pull.number,
    title: pull.title,
    merged_at: pull.merged_at,
    url: pull.html_url,
    author: pull.user?.login || 'unknown'
  }));

const commitSummaries = commits.map((commit) => ({
  sha: commit.sha?.slice(0, 7),
  message: (commit.commit?.message || '').split('\n')[0],
  author: commit.commit?.author?.name || commit.author?.login || 'unknown',
  date: commit.commit?.author?.date,
  url: commit.html_url
}));

return [{
  json: {
    repo: `${owner}/${repo}`,
    language,
    destinationWebhookUrl,
    since: sinceIso,
    until: untilIso,
    commits: commitSummaries,
    closedIssues,
    mergedPullRequests,
    counts: {
      commits: commitSummaries.length,
      closedIssues: closedIssues.length,
      mergedPullRequests: mergedPullRequests.length
    }
  }
}];

const data = $json;
const targetLanguage = data.language === 'FR' ? 'French' : 'English';
const prompt = `Write a concise weekly narrative engineering summary in ${targetLanguage} for ${data.repo}.

Time window: ${data.since} to ${data.until}

Counts:
- Commits: ${data.counts.commits}
- Closed issues: ${data.counts.closedIssues}
- Merged PRs: ${data.counts.mergedPullRequests}

Commits:
${JSON.stringify(data.commits, null, 2)}

Closed issues:
${JSON.stringify(data.closedIssues, null, 2)}

Merged pull requests:
${JSON.stringify(data.mergedPullRequests, null, 2)}

Output format:
1. A short title.
2. 2-4 narrative paragraphs focused on what changed and why it matters.
3. A compact bullet list of notable merged PRs and closed issues with links.
4. A closing sentence for stakeholders.
If there is little activity, say that clearly and summarize the quiet week without inventing work.`;

return [{
  json: {
    ...data,
    claudeRequest: {
      model: 'claude-sonnet-4-20250514',
      max_tokens: 1400,
      temperature: 0.2,
      messages: [
        {
          role: 'user',
          content: prompt
        }
      ]
    }
  }
}];

const claudeResponse = $json;
const source = $('Build Claude Request').first().json;
const contentBlocks = Array.isArray(claudeResponse.content) ? claudeResponse.content : [];
const summary = contentBlocks
  .filter((block) => block.type === 'text' && block.text)
  .map((block) => block.text)
  .join('\n\n')
  .trim();

if (!summary) {
  throw new Error('Claude response did not include text content.');
}

const heading = `Weekly GitHub activity summary for ${source.repo}`;
const metadata = `Window: ${source.since} to ${source.until} | Commits: ${source.counts.commits} | Closed issues: ${source.counts.closedIssues} | Merged PRs: ${source.counts.mergedPullRequests}`;
const content = `**${heading}**\n${metadata}\n\n${summary}`;

return [{
  json: {
    content,
    discordPayload: {
      content: content.length > 1900 ? `${content.slice(0, 1850)}\n\n...summary truncated for Discord.` : content
    }
  }
}];
